sp_theme.css_variables:
// ─── GateNow Brand Colors ───────────────────────────────
$brand-primary:               #5443AD !default;
$brand-primary-dark:          #3D3180 !default;
$brand-primary-darker:        #2E2460 !default;
$brand-primary-light:         #7B6EC4 !default;
$brand-primary-lighter:       #B8AFDF !default;
$brand-primary-lightest:      #EEEDFB !default;

// ─── Navbar (matches Figma gradient header) ─────────────
$navbar-inverse-bg:           #4B3FA0 !default;
$navbar-inverse-link-color:        #D4CFF5 !default;
$navbar-inverse-link-hover-color:  #FFFFFF !default;
$navbar-inverse-link-hover-bg:     rgba(255,255,255,0.10) !default;
$navbar-inverse-link-active-color: #FFFFFF !default;
$navbar-inverse-link-active-bg:    rgba(255,255,255,0.14) !default;
$sp-navbar-divider-color:          rgba(255,255,255,0.23) !default;

// ─── Body & Text ────────────────────────────────────────
$body-bg:                     #F5F6FA !default;
$text-color:                  #1D1D2E !default;
$text-muted:                  #6B7280 !default;
$link-color:                  #5443AD !default;
$link-hover-color:            #3D3180 !default;
$link-hover-decoration:       underline !default;

// ─── State Colors ────────────────────────────────────────
$brand-success:               #22C55E !default;
$brand-warning:               #F59E0B !default;
$brand-danger:                #EF4444 !default;
$brand-info:                  #6366F1 !default;

// ─── Buttons ─────────────────────────────────────────────
$btn-primary-bg:              $brand-primary !default;
$btn-primary-color:           #FFFFFF !default;
$btn-primary-border:          darken($brand-primary, 5%) !default;

$btn-success-bg:              $brand-success !default;
$btn-success-color:           #FFFFFF !default;
$btn-success-border:          darken($brand-success, 5%) !default;

$btn-default-color:           #2E2E2E !default;
$btn-disabled-opacity:        0.35 !default;

// ─── Inputs & Focus ──────────────────────────────────────
$input-border-focus:          #5443AD !default;
$input-border-tab-focus:      #5443AD !default;
$not-webkit-outline-color:    #5443AD !default;
$webkit-outline-color:        #5443AD !default;
$select2-container-active:    #5443AD !default;

// ─── Panels ──────────────────────────────────────────────
$panel-primary-border:        $brand-primary !default;
$panel-primary-heading-bg:    $brand-primary !default;
$panel-primary-text:          #FFFFFF !default;
$panel-list-item:             #EEEDFB !default;

// ─── Tagline / Login ─────────────────────────────────────
$sp-tagline-color:            #FFFFFF !default;
$login-btn-bg:                $brand-primary !default;
$login-btn-border:            darken($brand-primary, 5%) !default;

// ─── Quick Links ─────────────────────────────────────────
$quicklinks-background:       #EEEDFB !default;

// ─── Dropdown ────────────────────────────────────────────
$dropdown-link-active-bg:     $brand-primary !default;
$dropdown-link-active-color:  #FFFFFF !default;
$dropdown-link-disabled-color:#9CA3AF !default;

// ─── Component Active ────────────────────────────────────
$component-active-bg:         #F3F2FC !default;
$component-active-color:      $brand-primary !default;
$button-selected-color:       $brand-primary !default;

// ─── Alerts & States ─────────────────────────────────────
$state-success-bg:    #D1FAE5 !default;
$state-success-border:$brand-success !default;
$state-success-text:  #065F46 !default;

$state-warning-bg:    #FEF3C7 !default;
$state-warning-border:$brand-warning !default;
$state-warning-text:  #92400E !default;

$state-danger-bg:     #FEE2E2 !default;
$state-danger-border: $brand-danger !default;
$state-danger-text:   #991B1B !default;

$state-info-bg:       #EEF2FF !default;
$state-info-border:   $brand-info !default;
$state-info-text:     #3730A3 !default;

$alert-danger-bg:    $state-danger-bg !default;
$alert-danger-border:$state-danger-border !default;
$alert-danger-text:  $state-danger-text !default;
$alert-info-bg:      $state-info-bg !default;
$alert-info-border:  $state-info-border !default;
$alert-info-text:    $state-info-text !default;
$alert-success-bg:   $state-success-bg !default;
$alert-success-border:$state-success-border !default;
$alert-success-text: $state-success-text !default;
$alert-warning-bg:   $state-warning-bg !default;
$alert-warning-border:$state-warning-border !default;
$alert-warning-text: $state-warning-text !default;

// ─── Favourites Star ─────────────────────────────────────
$fav-star-color:         darken($brand-warning, 15%) !default;
$fav-star-color-off:     #FFFFFF !default;
$fav-star-outline-color: #92400E !default;
$fav-star-outline:       -1px 0 $fav-star-outline-color, 0 1px $fav-star-outline-color,
                          1px 0 $fav-star-outline-color, 0 -1px $fav-star-outline-color !default;

// ─── Data Table ──────────────────────────────────────────
$data-table-selected:    $brand-primary !default;
$widget-editor-fa-bg:    $brand-primary !default;
